def _ndarray_to_json(value: np.ndarray) -> dict:
    """Serialize a numpy array (including 0-d scalar arrays) to a JSON-friendly dict."""
    arr = np.asarray(value)
    return {
        "__ndarray__": arr.tolist(),
        "dtype": str(arr.dtype),
        "shape": list(arr.shape),
