def _json_to_ndarray(obj: dict) -> np.ndarray:
    """Restore a numpy array previously serialized by ``_ndarray_to_json``."""
    arr = np.asarray(obj["__ndarray__"], dtype=np.dtype(obj["dtype"]))
    return arr.reshape(tuple(obj["shape"]))


def save_tensors_data(tensors_data: "TensorsData", path: str | Path, smooth_quant: bool = False) -> None:
    """
    Serialize a :class:`TensorsData` object to a JSON file at ``path``.

    Missing parent directories are created automatically. The resulting JSON contains a top-level
    ``smooth_quant`` boolean field. Scalar numpy values (e.g. ``bins``) are stored as plain integers.
    """
    path = Path(path)
    if path.parent and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)

    data = {}
    for name in tensors_data.keys():
        tensor_data = tensors_data[name]
        entry = {}
        for attr in tensor_data._attrs:
            value = getattr(tensor_data, attr)
            if value is None:
                entry[attr] = None
            elif attr == "bins":
                # Scalar bin counts are serialized as plain integers.
                entry[attr] = int(value)
            else:
                entry[attr] = _ndarray_to_json(value)
        data[name] = entry

    payload = {
        "CLS": tensors_data.__class__.__name__,
        "calibration_method": tensors_data.calibration_method.name,
        "smooth_quant": bool(smooth_quant),
        "data": data,
    }

    with open(path, "w") as f:
        json.dump(payload, f)


