    with open(path) as f:
        payload = json.load(f)

    calibration_method = CalibrationMethod[payload["calibration_method"]]

    data = {}
    for name, entry in payload["data"].items():
        kwargs = {}
        for attr, value in entry.items():
            if value is None:
                kwargs[attr] = None
            elif attr == "bins":
                kwargs[attr] = int(value)
            elif isinstance(value, dict) and "__ndarray__" in value:
